import React, { useState, useEffect } from "react";

export default function AdminDepositRequests({ onCancel }) {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchPendingDeposits();
  }, []);

  // Date formatting helper
  const formatDate = (dateString) => {
    if (!dateString) return "Invalid Date"; // null or empty
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return "Invalid Date"; // invalid
    return date.toLocaleString(undefined, {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false,
    });
  };

  const fetchPendingDeposits = async () => {
    setLoading(true);
    setMessage("");
    try {
      const res = await fetch("http://localhost:8080/api/deposit/pending", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      if (!res.ok) throw new Error("Failed to load deposits");
      const data = await res.json();
      setRequests(data);
    } catch (err) {
      console.error("Fetch Error:", err);
      setMessage("❌ Failed to load deposits.");
    } finally {
      setLoading(false);
    }
  };

  const handleAction = async (id, action) => {
    try {
      const res = await fetch(
        `http://localhost:8080/api/deposit/${action}/${id}`,
        {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      if (!res.ok) throw new Error(`${action} failed`);
      setMessage(
        `✅ ${action.charAt(0).toUpperCase() + action.slice(1)}d successfully!`
      );
      fetchPendingDeposits();
    } catch (err) {
      setMessage(`❌ Failed to ${action}`);
    }
  };

  return (
    <div className="p-6">
      <h2 className="text-3xl font-bold text-center mb-4">
        🧾 Pending Deposit Requests
      </h2>

      {message && (
        <div
          className={`mb-4 px-4 py-3 rounded text-center font-semibold ${
            message.startsWith("✅")
              ? "bg-green-100 text-green-700"
              : "bg-red-100 text-red-700"
          }`}
        >
          {message}
        </div>
      )}

      {loading && <p className="text-center text-gray-500">Loading...</p>}
      {!loading && requests.length === 0 && (
        <p className="text-center text-gray-500">No pending requests.</p>
      )}

      {!loading && requests.length > 0 && (
        <div className="overflow-x-auto shadow-lg rounded-lg border border-gray-200">
          <table className="min-w-full bg-white text-sm">
            <thead className="bg-gray-100 border-b">
              <tr>
                <th className="py-3 px-4 text-center">ID</th>
                <th className="py-3 px-4 text-center">Game ID</th>
                <th className="py-3 px-4 text-center">Mobile</th>
                <th className="py-3 px-4 text-center">Amount</th>
                <th className="py-3 px-4 text-center">Method</th>
                <th className="py-3 px-4 text-center">Txn ID</th>
                <th className="py-3 px-4 text-center">Sender Number</th>
                <th className="py-3 px-4 text-center">Status</th>
                <th className="py-3 px-4 text-center">Requested At</th>
                <th className="py-3 px-4 text-center">Actions</th>
              </tr>
            </thead>
            <tbody>
              {requests.map((req) => (
                <tr
                  key={req.id}
                  className="border-b hover:bg-gray-50 transition"
                >
                  <td className="py-2 px-4 text-center">{req.id}</td>
                  <td className="py-2 px-4 text-center">
                    {req.gameId || "N/A"}
                  </td>
                  <td className="py-2 px-4 text-center">
                    {req.mobile || "N/A"}
                  </td>
                  <td className="py-2 px-4 text-center font-semibold text-green-600">
                    ৳ {Number(req.amount).toFixed(2)}
                  </td>
                  <td className="py-2 px-4 text-center">{req.method || "N/A"}</td>
                  <td className="py-2 px-4 text-center">
                    {req.transactionId || "N/A"}
                  </td>
                  <td className="py-2 px-4 text-center">
                    {req.senderNumber || "N/A"}
                  </td>
                  <td className="py-2 px-4 text-center">{req.status || "N/A"}</td>
                  <td className="py-2 px-4 text-center">
                    {formatDate(req.requestedAt)}
                  </td>
                  <td className="py-2 px-4 text-center">
                    <button
                      onClick={() => handleAction(req.id, "approve")}
                      disabled={req.status !== "PENDING"}
                      className="bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded mr-2 disabled:opacity-50"
                    >
                      Approve
                    </button>
                    <button
                      onClick={() => handleAction(req.id, "reject")}
                      disabled={req.status !== "PENDING"}
                      className="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded disabled:opacity-50"
                    >
                      Reject
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <div className="text-center mt-5">
        <button
          onClick={onCancel}
          className="bg-blue-500 hover:bg-blue-600 text-white px-5 py-2 rounded"
        >
          ⬅ Back to Home
        </button>
      </div>
    </div>
  );
}
